type Recommendation = { id: string; subject: string; topic: string; priority: 'high' | 'medium' | 'next'; titleKey: string; evidenceKey: string; evidence: Record<string, string | number>; tool: 'plan' | 'worksheet' | 'exam' };

function buildRecommendations(workspace: StudentLearningWorkspace): Recommendation[] {
  const recommendations: Recommendation[] = [];
  const grouped = workspace.assignments.reduce<Record<string, { scores: number[]; active: number; reviews: number }>>((acc, row) => {
    const subject = canonicalSubjectLabel(row.subject_label || row.subject_key);
    const stats = acc[subject] || { scores: [], active: 0, reviews: 0 };
    if (row.score_pct !== null && row.score_pct !== undefined && Number.isFinite(Number(row.score_pct))) stats.scores.push(Number(row.score_pct));
    if (!['graded', 'completed'].includes(String(row.status))) stats.active += 1;
    stats.reviews += workspace.reviews.filter((review) => String(review.assignment_id) === String(row.id) && String(review.status) === 'requested').length;
    acc[subject] = stats; return acc;
  }, {});
  const seenTopics = new Set<string>();
  workspace.assignments.forEach((row) => {
    const subject = canonicalSubjectLabel(row.subject_label || row.subject_key);
    const topic = String(row.topic || row.title || subject);
    const key = `${subject.toLocaleLowerCase()}::${topic.toLocaleLowerCase()}`;
    const score = row.score_pct === null || row.score_pct === undefined ? null : Number(row.score_pct);
    const reviewRequested = workspace.reviews.some((review) => String(review.assignment_id) === String(row.id) && String(review.status) === 'requested');
    if (seenTopics.has(key) || (!reviewRequested && (score === null || !Number.isFinite(score) || score >= 85))) return;
    seenTopics.add(key);
    recommendations.push({ id: `topic-${row.id}`, subject, topic, priority: reviewRequested || Number(score) < 65 ? 'high' : 'medium', titleKey: 'students.recReinforce', evidenceKey: reviewRequested ? 'students.recReviewEvidence' : 'students.recTopicEvidence', evidence: reviewRequested ? {} : { score: Math.round(Number(score)) }, tool: 'worksheet' });
  });
  Object.entries(grouped).forEach(([subject, stats]) => {
    const average = stats.scores.length ? Math.round(stats.scores.reduce((sum, score) => sum + score, 0) / stats.scores.length) : null;
    if (average !== null && average < 80 && !recommendations.some((item) => item.subject === subject)) recommendations.push({ id: `score-${subject}`, subject, topic: subject, priority: average < 65 || stats.reviews ? 'high' : 'medium', titleKey: 'students.recReinforce', evidenceKey: 'students.recScoreEvidence', evidence: { average, count: stats.scores.length }, tool: 'worksheet' });
    else if (average === null && stats.active) recommendations.push({ id: `diagnostic-${subject}`, subject, topic: subject, priority: 'medium', titleKey: 'students.recDiagnostic', evidenceKey: 'students.recDiagnosticEvidence', evidence: { count: stats.active }, tool: 'exam' });
  });
  workspace.programs.forEach((assignment) => {
    const program = (assignment.program || {}) as ClassioRecord;
    const topics = workspace.topics.filter((item) => String(item.program_id) === String(assignment.program_id));
    const progress = workspace.progress.filter((item) => String(item.assignment_id) === String(assignment.id));
    const progressByTopic = new Map(progress.map((item) => [String(item.topic_id), item]));
    const topic = topics.find((item) => !Boolean(progressByTopic.get(String(item.id))?.teacher_done));
    if (topic) recommendations.push({ id: `program-${assignment.id}-${topic.id}`, subject: canonicalSubjectLabel(program.subject), topic: String(topic.title || program.title || 'Next topic'), priority: 'next', titleKey: 'students.recContinue', evidenceKey: 'students.recProgramEvidence', evidence: { program: String(program.title || 'Learning program'), done: topics.filter((item) => Boolean(progressByTopic.get(String(item.id))?.teacher_done)).length, total: topics.length }, tool: 'plan' });
  });
  const order = { high: 0, medium: 1, next: 2 };
  return recommendations.sort((a, b) => order[a.priority] - order[b.priority]).slice(0, 4);
}

function Choice({ active, label, onPress }: { active: boolean; label: string; onPress: () => void }) { return <Pressable onPress={onPress} style={[styles.choice, active && styles.choiceActive]}><Text style={[styles.choiceText, active && styles.choiceTextActive]}>{label}</Text></Pressable>; }

type StudentSection = 'list' | 'connections' | 'progress';

function StudentSectionTabs({ section, studentCount, connectionCount, onChange }: { section: StudentSection; studentCount: number; connectionCount: number; onChange: (section: StudentSection) => void }) {
  const { t } = useAppPreferences();
  const tabs: { key: StudentSection; icon: string; label: string }[] = [
    { key: 'list', icon: '👩‍🎓', label: `${t('students.listTab')} (${studentCount})` },
    { key: 'connections', icon: '🤝', label: `${t('students.connectionsTab')} (${connectionCount})` },
    { key: 'progress', icon: '📈', label: t('students.progressTab') },
  ];
  return <View style={styles.directoryTabs}><TabRail accessibilityLabel={t('pages.students')} items={tabs.map((tab) => ({ value: tab.key, label: `${tab.icon} ${tab.label}` }))} value={section} onChange={onChange} /></View>;
}

function requestedScopes(connection: TeacherConnection) {
  if (!Array.isArray(connection.requested_subjects)) return [];
  return connection.requested_subjects.flatMap((item) => { const raw = typeof item === 'string' ? { subject_key: item, subject_label: item } : item as ClassioRecord; const key = canonicalSubjectKey(raw.subject_key || raw.subject_label); return key ? [{ key, label: canonicalSubjectLabel(raw.subject_label || raw.subject_key) }] : []; });
}

function ConnectionCard({ connection, busy, confirming, onRespond, onEnd }: { connection: TeacherConnection; busy: boolean; confirming: boolean; onRespond: (accept: boolean, subjects?: string[], rosterId?: string) => void; onEnd: () => void }) {
  const { t } = useAppPreferences();
  const requested = requestedScopes(connection);
  const [subjects, setSubjects] = useState(() => requested.map((item) => item.key));
  const suggestedCandidate = connection.roster_candidates.find((item) => item.match === 'email') || (connection.roster_candidates.length === 1 ? connection.roster_candidates[0] : null);
  const [rosterChoice, setRosterChoice] = useState(suggestedCandidate?.id || '__new__');
  const displayedSubjects = connection.subjects.length ? connection.subjects.map((row) => String(row.subject_label || row.subject_key)) : requested.map((item) => item.label);
  const toggleSubject = (key: string) => setSubjects((current) => current.includes(key) ? current.filter((item) => item !== key) : [...current, key]);
  return <Panel style={styles.connectionCard}><View style={styles.connectionMain}><View style={styles.avatar}><Text style={styles.avatarText}>{initials(connection.student_name)}</Text></View><View style={styles.connectionCopy}><Text style={styles.name}>{connection.student_name}</Text><Text style={styles.connectionMeta}>{connection.student_email || t('students.noSharedEmail')} · {String(connection.status || 'pending')}</Text>{String(connection.status) !== 'pending' ? <Text style={styles.connectionSubjects}>{displayedSubjects.filter(Boolean).join(' · ')}</Text> : null}{connection.request_note ? <Text style={styles.cardNotes}>{String(connection.request_note)}</Text> : null}</View></View>{String(connection.status) === 'pending' ? <View style={styles.connectionReview}><Text style={styles.label}>{t('students.requestedSubjects')}</Text><Text style={styles.inlineHelp}>{t('students.subjectHelp')}</Text><View style={styles.subjectPicker}>{requested.map((subject) => <Choice key={subject.key} active={subjects.includes(subject.key)} label={subject.label} onPress={() => toggleSubject(subject.key)} />)}</View>{connection.roster_candidates.length ? <SelectField label={t('students.rosterResolution')} value={rosterChoice} options={[{ value: '__new__', label: t('students.createRoster') }, ...connection.roster_candidates.map((candidate) => ({ value: candidate.id, label: candidate.student, detail: `${candidate.email || t('students.noSharedEmail')} · ${t(candidate.match === 'email' ? 'students.matchEmail' : 'students.matchName')}` }))]} help={t('students.rosterHelp')} onChange={setRosterChoice} /> : <Text style={styles.inlineHelp}>{t('students.createRoster')}</Text>}<View style={styles.connectionActions}><Button disabled={busy || !subjects.length} onPress={() => onRespond(true, subjects, rosterChoice === '__new__' ? undefined : rosterChoice)}>{t('students.acceptLink')}</Button><Button secondary disabled={busy} onPress={() => onRespond(false)}>{t('students.reject')}</Button></View></View> : String(connection.status) === 'active' ? <View style={styles.connectionActions}><Button secondary disabled={busy} onPress={onEnd}>{confirming ? t('students.confirmEndConnection') : t('students.endConnection')}</Button></View> : null}</Panel>;
}

